#!/usr/bin/env python3

import argparse
import json
import pathlib
import subprocess
import unittest

import yaml


ROOT = pathlib.Path(__file__).resolve().parents[2]
WORKFLOWS = (
    ROOT / ".github/workflows/shared/test-reviewer-shared.md",
    ROOT / ".github/workflows/test-reviewer-on-pr.agent.md",
    ROOT / ".github/workflows/test-reviewer.agent.md",
)
WORKFLOW_NAME = "Test quality review"
RUN_URL = "https://github.com/example/testfx/actions/runs/123"
HISTORY_URL = "https://github.com/search?q=repo%3Aexample%2Ftestfx"
EXPECTED_FOOTER = (
    f"> \U0001f916 **Automated content by GitHub Copilot.** Generated by the "
    f"[{WORKFLOW_NAME}]({RUN_URL}/agentic_workflow) workflow."
)
NODE_HARNESS = r"""
const fs = require("fs");
const path = require("path");
const input = JSON.parse(fs.readFileSync(0, "utf8"));
global.core = { info() {}, warning() {}, debug() {} };
global.github = {};
global.context = { repo: { owner: "example", repo: "testfx" }, payload: {} };
for (const key of [
  "GH_AW_AIC", "GH_AW_AGENT_AIC", "GH_AW_EVALS_AIC",
  "GH_AW_THREAT_DETECTION_AIC", "GH_AW_AMBIENT_CONTEXT",
  "GH_AW_ENGINE_ID", "GH_AW_ENGINE_MODEL",
]) {
  delete process.env[key];
}
process.env.GH_AW_SAFE_OUTPUT_MESSAGES = JSON.stringify({ footer: input.footer });
const { getFooterMessage } = require(path.join(input.scriptsDirectory, "messages_footer.cjs"));
const output = getFooterMessage({
  workflowName: input.workflowName,
  runUrl: input.runUrl,
  historyUrl: input.historyUrl,
});
console.log(JSON.stringify({ output }));
"""


class GhAwReviewFooterTests(unittest.TestCase):
    def check_footer(self, history_url: str | None) -> None:
        expected = EXPECTED_FOOTER
        if history_url:
            expected += f" \u00b7 [\u25f7]({history_url})"
        for workflow in WORKFLOWS:
            with self.subTest(workflow=workflow.name, history=bool(history_url)):
                frontmatter = yaml.safe_load(workflow.read_text(encoding="utf-8").split("---", 2)[1])
                footer = frontmatter["safe-outputs"]["messages"]["footer"]
                result = subprocess.run(
                    ["node", "-e", NODE_HARNESS],
                    input=json.dumps(
                        {
                            "scriptsDirectory": str(SCRIPTS_DIRECTORY),
                            "footer": footer,
                            "workflowName": WORKFLOW_NAME,
                            "runUrl": RUN_URL,
                            "historyUrl": history_url,
                        }
                    ),
                    encoding="utf-8",
                    capture_output=True,
                    check=True,
                    timeout=30,
                )
                self.assertEqual(expected, json.loads(result.stdout)["output"])

    def test_absent_history_omits_the_entire_optional_fragment(self) -> None:
        self.check_footer(None)

    def test_present_history_expands_one_complete_link(self) -> None:
        self.check_footer(HISTORY_URL)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--scripts-directory", type=pathlib.Path, required=True)
    args, unittest_args = parser.parse_known_args()
    SCRIPTS_DIRECTORY = args.scripts_directory.resolve()
    unittest.main(argv=[__file__, *unittest_args])
